import pandas as pd
import re

df_orig = pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)
df_harm = pd.read_csv('/root/ckd_lab_data_harmonized.csv')

# Remove rows with missing from original for comparison (get same rows)
numeric_cols = [c for c in df_orig.columns if c != 'patient_id']

def parse_value(value):
    if pd.isna(value):
        return float('nan')
    s = str(value).strip()
    if s in ('', 'NaN', 'nan', 'None', 'none'):
        return float('nan')
    if 'e' in s.lower():
        try:
            return float(s)
        except ValueError:
            pass
    if ',' in s:
        s = s.replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return float('nan')

# Spot-check row 0: patient_id=1
print('=== Patient 1 Spot Check ===')
orig = df_orig.iloc[0]
harm = df_harm.iloc[0]

checks = [
    ('Serum_Creatinine', 'µmol/L->mg/dL (*0.0113)'),
    ('Hemoglobin', 'g/L->g/dL (*0.1) or mmol/L->g/dL (*1.611)'),
    ('Serum_Calcium', 'mmol/L->mg/dL (*4.0)'),
    ('Albumin_Serum', 'g/L->g/dL (*0.1)'),
    ('Total_Protein', 'g/L->g/dL (*0.1)'),
]

for col, conv_note in checks:
    o = orig[col]
    parsed = parse_value(o)
    h = harm[col]
    print(f'{col}: orig=\"{o}\" -> parsed={parsed:.4f} -> harmonized={h} ({conv_note})')

print()
print('=== Summary Statistics ===')
for col in ['Serum_Creatinine', 'Hemoglobin', 'Glucose', 'Serum_Calcium', 'Total_Cholesterol']:
    vals = df_harm[col]
    print(f'{col}: min={vals.min():.2f}, max={vals.max():.2f}, mean={vals.mean():.2f}')
"
